export const PROJECTOR_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<meta name=\"theme-color\" content=\"#1a4a2e\">\n<title>Leaderboard - Team Connect Puzzle Challenge</title>\n<link rel=\"icon\" href=\"/favicon.png\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700;800;900&display=swap\">\n<style>\n/* ============================================================\n   TEAM CONNECT BRAND BLOCK (matches the site: green #1a4a2e, gold #c9a84c, Montserrat)\n   ============================================================ */\n:root {\n  --brand-primary: #1a4a2e;\n  --brand-primary-dark: #123520;\n  --brand-accent: #c9a84c;\n  --brand-accent-dark: #8a6d1c;   /* gold dark enough for text on white */\n  --brand-bg: #f7f5f0;\n  --brand-card: #ffffff;\n  --brand-text: #222222;\n  --brand-muted: #5f6b64;\n  --brand-line: #ddd8cb;\n  --font-body: \"Montserrat\", \"Segoe UI\", system-ui, -apple-system, Roboto, Arial, sans-serif;\n  --font-head: \"Montserrat\", \"Segoe UI\", system-ui, -apple-system, Roboto, Arial, sans-serif;\n\n  --ok: #1e9e4a; --ok-bg: #e6f6ec;\n  --bad: #d62f3a; --bad-bg: #fdecee;\n  --radius: 14px;\n}\n\n* { box-sizing: border-box; }\nhtml { -webkit-text-size-adjust: 100%; }\nbody {\n  margin: 0; background: var(--brand-bg); color: var(--brand-text);\n  font-family: var(--font-body); font-size: 17px; line-height: 1.4;\n  -webkit-tap-highlight-color: transparent;\n}\nh1, h2, h3 { font-family: var(--font-head); margin: 0; line-height: 1.15; }\nbutton, input, select { font: inherit; }\n[hidden] { display: none !important; }\n\n/* ---------- buttons and inputs (large tap targets) ---------- */\n.btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  min-height: 48px; padding: 0 20px; border: 0; border-radius: 12px;\n  background: var(--brand-primary); color: #fff; font-weight: 700; cursor: pointer;\n  touch-action: manipulation;\n}\n.btn:active { transform: translateY(1px); }\n.btn:disabled { opacity: .5; cursor: default; }\n.btn.accent { background: var(--brand-accent); color: #1a2a10; }\n.btn.ghost { background: transparent; color: var(--brand-primary); border: 2px solid var(--brand-primary); }\n.btn.danger { background: var(--bad); }\n.btn.block { width: 100%; }\n.btn.small { min-height: 38px; padding: 0 14px; font-size: 15px; border-radius: 10px; }\n.field {\n  width: 100%; min-height: 50px; padding: 0 14px; border: 2px solid var(--brand-line); border-radius: 12px;\n  background: #fff; color: var(--brand-text); font-size: 18px;\n}\n.field:focus { outline: 0; border-color: var(--brand-accent); box-shadow: 0 0 0 3px rgba(232,134,42,.25); }\nselect.field { appearance: auto; }\nlabel.lbl { display: block; font-weight: 700; margin: 14px 0 6px; }\n.muted { color: var(--brand-muted); }\n.err { color: var(--bad); font-weight: 700; }\n\n/* ---------- brand header ---------- */\n.brandbar { background: var(--brand-primary); color: #fff; padding: 14px 16px; display: flex; align-items: center; gap: 12px; }\n.brandbar img { height: 64px; width: auto; display: block; }\n.brandbar .wordmark { font-weight: 800; letter-spacing: .08em; font-size: 18px; }\n.brandbar .tag { font-size: 13px; opacity: .85; margin-left: auto; text-align: right; line-height: 1.25; }\n\n.screen { max-width: 560px; margin: 0 auto; padding: 18px 16px 40px; }\n.panel { background: var(--brand-card); border-radius: var(--radius); padding: 20px; box-shadow: 0 1px 3px rgba(0,0,0,.08); }\n.hero h1 { font-size: 28px; color: var(--brand-primary); }\n.hero p { margin: 10px 0 0; }\n.footer-tag { text-align: center; color: var(--brand-muted); font-size: 14px; margin-top: 26px; }\n\n/* ---------- waiting ---------- */\n.pulse { width: 74px; height: 74px; border-radius: 50%; background: var(--brand-accent); margin: 8px auto 18px; animation: pulse 1.6s ease-in-out infinite; }\n@keyframes pulse { 0%,100% { transform: scale(.82); opacity: .6; } 50% { transform: scale(1); opacity: 1; } }\n.center { text-align: center; }\n\n/* ---------- sticky game bar ---------- */\n.gamebar { position: sticky; top: 0; z-index: 20; background: var(--brand-primary); color: #fff; padding: 8px 12px 10px; box-shadow: 0 2px 8px rgba(0,0,0,.25); }\n.gamebar .row { display: flex; align-items: center; gap: 10px; max-width: 760px; margin: 0 auto; }\n.gamebar .team { font-weight: 700; font-size: 14px; opacity: .9; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 1; min-width: 0; }\n.timer { font-variant-numeric: tabular-nums; font-weight: 800; font-size: 34px; letter-spacing: .02em; line-height: 1; }\n.timer.low { color: #f3d27a; }\n.timer.crit { color: #ff6b6b; animation: blink 1s steps(2) infinite; }\n@keyframes blink { 50% { opacity: .55; } }\n.gamebar .btn { min-height: 40px; padding: 0 14px; font-size: 15px; }\n.progress { max-width: 760px; margin: 8px auto 0; }\n.progress .label { font-size: 13px; opacity: .9; margin-bottom: 4px; display: flex; justify-content: space-between; }\n.progress .track { height: 10px; background: rgba(255,255,255,.22); border-radius: 6px; overflow: hidden; }\n.progress .fill { height: 100%; background: var(--brand-accent); width: 0; transition: width .5s; }\n\n.main { max-width: 760px; margin: 0 auto; padding: 14px 12px 60px; }\n.section-title { font-size: 20px; color: var(--brand-primary); margin: 22px 4px 10px; display: flex; align-items: center; gap: 8px; }\n.grid2 { display: grid; gap: 12px; grid-template-columns: 1fr; }\n@media (min-width: 640px) { .grid2 { grid-template-columns: 1fr 1fr; } }\n\n/* ---------- cards ---------- */\n.card { background: var(--brand-card); border: 2px solid var(--brand-line); border-radius: var(--radius); overflow: hidden; }\n.card > header { padding: 10px 14px; background: #edeadf; display: flex; align-items: center; gap: 8px; font-weight: 800; color: var(--brand-primary); }\n.card > header .state { margin-left: auto; font-size: 13px; font-weight: 700; padding: 3px 10px; border-radius: 20px; background: #dde5ec; color: var(--brand-muted); }\n.card .body { padding: 14px; }\n.clue-text { text-align: center; font-weight: 800; font-size: 19px; line-height: 1.3; padding: 10px 4px; color: var(--brand-primary); letter-spacing: .01em; }\n.card.open { border-color: var(--ok); }\n.card.open > header { background: var(--ok-bg); }\n.card.open > header .state { background: var(--ok); color: #fff; }\n.card.done > header .state { background: var(--ok); color: #fff; }\n.pwrow { display: flex; gap: 8px; }\n.pwrow .field { flex: 1; min-width: 0; letter-spacing: .04em; }\n.pwrow .btn { flex: none; }\n.msg { min-height: 22px; margin-top: 8px; font-weight: 700; }\n.msg.bad { color: var(--bad); }\n.note { font-size: 14px; color: var(--brand-muted); margin-top: 8px; }\n.shake { animation: shake .45s; border-color: var(--bad) !important; }\n@keyframes shake { 0%,100% { transform: translateX(0); } 15% { transform: translateX(-9px); } 35% { transform: translateX(9px); } 55% { transform: translateX(-7px); } 75% { transform: translateX(6px); } }\n.field.bad { border-color: var(--bad); background: var(--bad-bg); }\n.field.good { border-color: var(--ok); background: var(--ok-bg); font-weight: 700; }\n\n.q { padding: 12px 0; border-top: 1px solid var(--brand-line); }\n.q:first-of-type { border-top: 0; padding-top: 0; }\n.q .qid { font-weight: 800; color: var(--brand-accent-dark); margin-bottom: 4px; display: flex; align-items: center; gap: 8px; }\n.q .qtext { margin-bottom: 10px; }\n.q .tick { color: var(--ok); font-size: 22px; line-height: 1; }\n.q .ansrow { display: flex; gap: 8px; }\n.q .ansrow .field { flex: 1; min-width: 0; }\n.trio { display: grid; grid-template-columns: auto 1fr; gap: 8px 10px; align-items: center; margin-bottom: 10px; }\n.trio b { font-size: 17px; }\n\n/* ---------- modal ---------- */\n.modal { position: fixed; inset: 0; z-index: 50; background: rgba(8,20,32,.78); display: flex; align-items: flex-start; justify-content: center; overflow-y: auto; padding: 12px; }\n.modal .sheet { background: #fff; border-radius: 16px; width: 100%; max-width: 520px; padding: 16px; margin: auto; }\n.modal h2 { font-size: 22px; color: var(--brand-primary); margin-bottom: 10px; }\n.modal .actions { margin-top: 14px; display: flex; gap: 10px; }\n.brief-text p { margin: 0 0 12px; font-size: 18px; }\n\n/* ---------- sudoku ---------- */\n.sudoku-wrap { width: min(100%, 440px); margin: 0 auto; }\n.sudoku { display: grid; grid-template-columns: repeat(9, 1fr); border: 3px solid #111; background: #111; gap: 0; user-select: none; -webkit-user-select: none; }\n.sudoku .cell {\n  position: relative; aspect-ratio: 1; display: flex; align-items: center; justify-content: center;\n  background: #fff; border: 0; padding: 0; margin: 0; color: #000; font-size: clamp(16px, 5.4vw, 26px); font-weight: 700;\n  border-right: 1px solid #9aa5af; border-bottom: 1px solid #9aa5af; border-radius: 0; cursor: pointer; touch-action: manipulation;\n}\n.sudoku .cell:nth-child(9n) { border-right: 0; }\n.sudoku .cell:nth-child(n+73) { border-bottom: 0; }\n.sudoku .cell.bR { border-right: 3px solid #111; }\n.sudoku .cell.bB { border-bottom: 3px solid #111; }\n.sudoku .cell.given { cursor: default; }\n.sudoku .cell .letter { color: #e11d2e; font-weight: 800; }\n.sudoku .cell .scratch { color: #2563eb; font-weight: 600; font-style: italic; }\n.sudoku .cell .letter.small { position: absolute; top: 1px; left: 3px; font-size: clamp(9px, 2.6vw, 12px); }\n.sudoku .cell.sel { background: #fbf1cf; box-shadow: inset 0 0 0 3px var(--brand-accent); }\n.sudoku .cell.hl { background: #f2f6fa; }\n.sudoku.mini { border-width: 2px; pointer-events: none; width: 100%; }\n.sudoku.mini .cell { font-size: 9px; border-right-width: 0; border-bottom-width: 0; }\n.sudoku.mini .cell.bR { border-right: 2px solid #111; }\n.sudoku.mini .cell.bB { border-bottom: 2px solid #111; }\n.sudoku.mini .cell .letter.small { font-size: 6px; }\n.pad { display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px; margin-top: 12px; }\n.pad button { min-height: 52px; border-radius: 10px; border: 2px solid var(--brand-line); background: #fff; font-size: 22px; font-weight: 700; color: var(--brand-primary); touch-action: manipulation; }\n.pad button:active { background: #edeadf; }\n.pad button.wide { grid-column: span 2; font-size: 16px; }\n.clue-open { display: block; width: 100%; background: none; border: 0; padding: 0; cursor: pointer; }\n.clue-open .tap { text-align: center; font-weight: 800; color: var(--brand-accent-dark); margin-top: 10px; }\n\n/* ---------- overlay & finish ---------- */\n.overlay { position: fixed; inset: 0; z-index: 40; background: rgba(8,20,32,.88); color: #fff; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 24px; }\n.overlay h2 { font-size: 30px; margin-bottom: 10px; }\n.finish .bigscore { font-size: 76px; font-weight: 900; color: var(--brand-accent-dark); line-height: 1; }\n.stats { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 18px 0; }\n.stat { background: #f1eee4; border-radius: 12px; padding: 12px; }\n.stat b { display: block; font-size: 24px; color: var(--brand-primary); font-variant-numeric: tabular-nums; }\n.stat span { font-size: 14px; color: var(--brand-muted); }\n.toast { position: fixed; left: 50%; bottom: 20px; transform: translateX(-50%); background: #111; color: #fff; padding: 12px 20px; border-radius: 10px; z-index: 80; font-weight: 700; max-width: 90vw; }\n.testflag { background: #7c3aed; color: #fff; text-align: center; font-weight: 800; font-size: 13px; padding: 4px; letter-spacing: .06em; }\n\n/* =====================================================\n   Facilitator console\n   ===================================================== */\n.fac { max-width: 1100px; margin: 0 auto; padding: 16px 14px 60px; }\n.fac h2 { color: var(--brand-primary); font-size: 22px; margin-bottom: 12px; }\n.fac .cols { display: grid; gap: 16px; grid-template-columns: 1fr; }\n@media (min-width: 900px) { .fac .cols { grid-template-columns: 320px 1fr; align-items: start; } }\n.clientlist { display: flex; flex-direction: column; gap: 8px; margin-top: 12px; }\n.clientitem { text-align: left; background: #fff; border: 2px solid var(--brand-line); border-radius: 12px; padding: 10px 12px; cursor: pointer; display: block; width: 100%; color: inherit; }\n.clientitem.sel { border-color: var(--brand-accent); background: #fff8ee; }\n.clientitem b { display: block; }\n.badge { display: inline-block; font-size: 12px; font-weight: 800; padding: 2px 9px; border-radius: 20px; background: #dde5ec; color: var(--brand-muted); text-transform: uppercase; letter-spacing: .04em; }\n.badge.running { background: var(--ok); color: #fff; }\n.badge.paused { background: #f59e0b; color: #1c1203; }\n.badge.ended { background: #64748b; color: #fff; }\n.badge.test { background: #7c3aed; color: #fff; }\n.bigclock { font-size: 56px; font-weight: 900; font-variant-numeric: tabular-nums; color: var(--brand-primary); line-height: 1; }\n.ctrls { display: flex; flex-wrap: wrap; gap: 8px; margin: 12px 0; }\n.linkbox { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }\n.linkbox input { flex: 1; min-width: 200px; }\n.qrbox { background: #fff; padding: 10px; border-radius: 10px; display: inline-block; border: 1px solid var(--brand-line); }\n.qrbox svg, .qrbox img { display: block; width: 190px; height: 190px; }\n.tablewrap { overflow-x: auto; }\ntable.tbl { width: 100%; border-collapse: collapse; font-size: 15px; }\n.tbl th { text-align: left; padding: 8px 10px; background: #edeadf; color: var(--brand-primary); font-size: 13px; text-transform: uppercase; letter-spacing: .04em; white-space: nowrap; }\n.tbl td { padding: 10px; border-bottom: 1px solid var(--brand-line); white-space: nowrap; font-variant-numeric: tabular-nums; }\n.tbl tr.row { cursor: pointer; }\n.tbl tr.row:hover { background: #f7fafc; }\n.tbl td.rank { font-weight: 900; font-size: 18px; }\n.tbl td.score { font-weight: 900; font-size: 18px; color: var(--brand-primary); }\n.dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%; background: #c4ccd4; margin-right: 6px; }\n.dot.on { background: var(--ok); }\n.timeline { list-style: none; margin: 10px 0 0; padding: 0; max-height: 52vh; overflow-y: auto; }\n.timeline li { display: flex; gap: 12px; padding: 7px 0; border-bottom: 1px solid var(--brand-line); font-size: 15px; }\n.timeline .t { font-variant-numeric: tabular-nums; font-weight: 800; color: var(--brand-primary); min-width: 54px; }\n.timeline .wrong { color: var(--bad); }\n.timeline .good { color: var(--ok); font-weight: 700; }\n.keytable td, .keytable th { white-space: normal; vertical-align: top; }\n.row-inline { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }\n.mt { margin-top: 16px; }\n\n/* =====================================================\n   Projector view (dark, readable across a room)\n   ===================================================== */\nbody.proj { background: #0c1f14; color: #fff; overflow-x: hidden; }\n.proj .wrap { max-width: 1500px; margin: 0 auto; padding: 2.2vh 3vw; }\n.proj .top { display: flex; align-items: center; justify-content: space-between; gap: 2vw; }\n.proj .top h1 { font-size: clamp(26px, 4.2vw, 64px); }\n.proj .top .sub { font-size: clamp(14px, 1.6vw, 24px); color: #a9bfb1; margin-top: .6vh; }\n.proj .clock { font-size: clamp(54px, 10vw, 170px); font-weight: 900; font-variant-numeric: tabular-nums; line-height: 1; color: var(--brand-accent); }\n.proj .clock.paused { color: #f59e0b; }\n.proj .clock.ended { color: #94a3b8; }\n.proj .clock.crit { color: #ff6b6b; }\n.proj .board { margin-top: 2.5vh; display: flex; flex-direction: column; gap: 1.1vh; }\n.proj .line { display: grid; grid-template-columns: 6vw 1fr 14vw 14vw; align-items: center; gap: 1vw; background: #12301f; border-radius: 1.2vw; padding: 1.4vh 2vw; font-size: clamp(20px, 3.1vw, 52px); }\n.proj .line.head { background: none; color: #86a08f; font-size: clamp(12px, 1.4vw, 22px); text-transform: uppercase; letter-spacing: .08em; padding-top: 0; padding-bottom: 0; }\n.proj .line .r { font-weight: 900; color: var(--brand-accent); }\n.proj .line .n { font-weight: 800; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.proj .line .s { text-align: right; font-weight: 900; font-variant-numeric: tabular-nums; }\n.proj .line .a { text-align: right; font-variant-numeric: tabular-nums; color: #cfdcd3; }\n.proj .line.first { background: #3a2f0d; outline: .25vw solid var(--brand-accent); }\n.proj .empty { text-align: center; color: #86a08f; font-size: clamp(20px, 2.6vw, 40px); margin-top: 8vh; }\n\n</style>\n</head>\n<body class=\"proj\">\n<div id=\"app\"></div>\n<noscript><p style=\"padding:20px\">This activity needs JavaScript. Please use a current phone browser.</p></noscript>\n<script>\n(function () {\n  'use strict';\n  var app = document.getElementById('app');\n  var code = (new URLSearchParams(location.search).get('client') || '').toUpperCase();\n  var d = null, at = 0;\n  function h(tag, props) {\n    var el = document.createElement(tag);\n    if (props) for (var k in props) { var v = props[k]; if (v == null || v === false) continue; if (k === 'class') el.className = v; else if (k === 'text') el.textContent = v; else el.setAttribute(k, v); }\n    for (var i = 2; i < arguments.length; i++) { var c = arguments[i]; if (c != null) el.appendChild(typeof c === 'string' ? document.createTextNode(c) : c); }\n    return el;\n  }\n  function mmss(ms) { var s = Math.max(0, Math.ceil(ms / 1000)); return String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0'); }\n  var STATUS = { waiting: 'Waiting to start', running: 'Time left', paused: 'Paused', ended: 'Finished' };\n  if (!code) {\n    app.appendChild(h('div', { class: 'wrap' }, h('h1', { text: 'Projector view' }), h('p', { class: 'empty', text: 'Open this from the facilitator console (sign in there first, in this same browser).' }), h('p', { class: 'empty' }, h('a', { href: '/puzzle/facilitator', style: 'color:#e8862a', text: 'Go to facilitator console' }))));\n    return;\n  }\n  var title = h('h1'), sub = h('div', { class: 'sub' }), clock = h('div', { class: 'clock' }), status = h('div', { class: 'sub', style: 'text-align:right' }), board = h('div', { class: 'board' });\n  app.appendChild(h('div', { class: 'wrap' },\n    h('div', { class: 'top' }, h('div', null, title, sub), h('div', null, clock, status)), board));\n  function load() {\n    fetch('/api/puzzle/fac/clients/' + code, { credentials: 'same-origin', cache: 'no-store' }).then(function (r) {\n      if (r.status === 401) { board.textContent = ''; board.appendChild(h('p', { class: 'empty', text: 'Not signed in. Sign in on the facilitator console, then reload this page.' })); return null; }\n      return r.json();\n    }).then(function (j) { if (j && j.code) { d = j; at = Date.now(); paint(); } }).catch(function () {});\n  }\n  function paint() {\n    title.textContent = d.name;\n    sub.textContent = 'Team Connect Puzzle Challenge · Leaderboard';\n    status.textContent = STATUS[d.status];\n    while (board.firstChild) board.removeChild(board.firstChild);\n    if (!d.teams.length) { board.appendChild(h('p', { class: 'empty', text: 'Waiting for teams to join…' })); return; }\n    board.appendChild(h('div', { class: 'line head' }, h('div', { text: '#' }), h('div', { text: 'Team' }), h('div', { class: 'a', text: 'Answers' }), h('div', { class: 's', text: 'Score' })));\n    d.teams.slice(0, 12).forEach(function (t, i) {\n      board.appendChild(h('div', { class: 'line' + (t.rank === 1 && t.score > 0 ? ' first' : '') },\n        h('div', { class: 'r', text: String(t.rank) }), h('div', { class: 'n', text: t.name + (t.finished ? ' ✔' : '') }),\n        h('div', { class: 'a', text: t.correct + '/' + t.total }), h('div', { class: 's', text: String(t.score) })));\n    });\n    if (d.teams.length > 12) board.appendChild(h('p', { class: 'empty', text: '+ ' + (d.teams.length - 12) + ' more teams' }));\n  }\n  function paintClock() {\n    if (!d) return;\n    var left = d.timeLeftMs;\n    if (d.status === 'running') left = Math.max(0, d.timeLeftMs - (Date.now() - at));\n    clock.textContent = mmss(d.status === 'waiting' ? d.durationMs : left);\n    clock.className = 'clock' + (d.status === 'paused' ? ' paused' : d.status === 'ended' ? ' ended' : d.status === 'running' && left <= 60000 ? ' crit' : '');\n  }\n  load(); setInterval(load, 2000); setInterval(paintClock, 250);\n})();\n\n</script>\n</body>\n</html>\n";
